import { describe, expect, it } from "vitest";
import { buildEnvLocal } from "../../src/core/apply/index.js";

describe("buildEnvLocal", () => {
  const example = ["# Database", "DATABASE_URL=postgresql://localhost/db", "JWT_SECRET=change-me-32-bytes", "API_SECRET=", "PORT=8080", ""].join("\n");

  it("copies the example, generates placeholder secrets, keeps comments", () => {
    const { text, generated } = buildEnvLocal(example, [], ".env.example", () => "s3cr3t");
    expect(generated).toEqual(["JWT_SECRET", "API_SECRET"]);
    expect(text.split("\n")).toEqual([
      "# Generated by create-forge-app from .env.example. Local values only: never commit this file.",
      "# Database",
      "DATABASE_URL=postgresql://localhost/db",
      "JWT_SECRET=s3cr3t",
      "API_SECRET=s3cr3t",
      "PORT=8080",
      "",
    ]);
  });

  it("keeps a real secret value and appends planned variables missing from the example", () => {
    const { text, generated } = buildEnvLocal("JWT_SECRET=already-set\n", [{ key: "SMTP_HOST", value: "" }, { key: "JWT_SECRET", value: "" }], "env.example");
    expect(generated).toEqual([]);
    expect(text).toContain("JWT_SECRET=already-set");
    expect(text).toContain("SMTP_HOST=\n");
  });

  it("random secrets are 64 hex chars and differ", () => {
    const a = buildEnvLocal("A_SECRET=\n", [], "e").text;
    const b = buildEnvLocal("A_SECRET=\n", [], "e").text;
    expect(a).toMatch(/A_SECRET=[0-9a-f]{64}/);
    expect(a).not.toBe(b);
  });
});
